# RGB-derived: docs/store_tools_in_toolbox/applied_values.json (rgb_derived_values).
"""RGB geometry updates generated by --run-geometry-fitting.

Evidence: docs/store_tools_in_toolbox/geometry_fit.json

Inputs at run time: current RGB, camera calibration and proprioception. The survey measures the tray's frame and each
tool's outline, position, direction and side from the head picture. Declared constants: the size of each tool's
outline (to tell the tools apart), where each tool's outline middle rests in the tray's frame, the pinch point in each
tool's frame, and motion constants.
"""
import json
import math
import numpy as np
from PIL import Image, ImageDraw

TABLE_Z = 0.764649746
LOG = []


def cam(robo, name='cam_head'):
    m = robo.camera_meta(name)
    return np.asarray(m['intrinsic_matrix'], float), np.asarray(m['extrinsic_matrix'], float)


def pixel_ray(K, E, rc):
    """World origin and unit direction of the ray through pixel (row, col)."""
    r, c = float(rc[0]), float(rc[1])
    d = E[:3, :3] @ np.array([(c - K[0, 2]) / K[0, 0], -(r - K[1, 2]) / K[1, 1], -1.0])
    return E[:3, 3].copy(), d / np.linalg.norm(d)


def ray_at_z(K, E, rc, z):
    o, d = pixel_ray(K, E, rc)
    return o + (z - o[2]) / d[2] * d


def project(K, E, pts):
    """World points -> (row, col) pixels."""
    P = np.atleast_2d(np.asarray(pts, float))
    pc = (P - E[:3, 3]) @ E[:3, :3]
    col = K[0, 2] + K[0, 0] * pc[:, 0] / -pc[:, 2]
    row = K[1, 2] - K[1, 1] * pc[:, 1] / -pc[:, 2]
    return np.c_[row, col]


def mask_of(seg, shape=(480, 640)):
    """Rasterize a Segment's outlines into a boolean mask."""
    im = Image.new('L', (shape[1], shape[0]), 0)
    dr = ImageDraw.Draw(im)
    for outline in seg.contours_rc or ():
        pts = [(int(c), int(r)) for r, c in outline]
        if len(pts) >= 3:
            dr.polygon(pts, fill=255)
    return np.asarray(im) > 0


def carve_holes(filled, area_px, rgb):
    """Remove enclosed background from a mask rasterized from outer outlines.

    ``robo.segment`` returns outer outlines and the true mask area. When the
    filled outline is larger than that area, the object encloses background
    (the table seen through a headband). The enclosed pixels that look most
    like the background just outside the outline are removed, up to the
    missing area.
    """
    import cv2
    extra = int(filled.sum()) - int(area_px)
    if area_px <= 0 or extra < 0.06 * filled.sum():
        return filled
    f = filled.astype(np.uint8)
    ring = (cv2.dilate(f, np.ones((15, 15), np.uint8)) > 0) & ~(cv2.dilate(f, np.ones((5, 5), np.uint8)) > 0)
    if ring.sum() < 50:
        return filled
    lab = cv2.cvtColor(np.ascontiguousarray(np.asarray(rgb)[:, :, :3]), cv2.COLOR_RGB2LAB).astype(np.float32)
    bg = lab[ring]
    mu, sd = bg.mean(axis=0), bg.std(axis=0) + 4.0
    inner = (cv2.erode(f, np.ones((3, 3), np.uint8)) > 0)
    d = np.full(filled.shape, np.inf, np.float32)
    d[inner] = np.sqrt((((lab[inner] - mu) / sd) ** 2).sum(axis=1))
    order = np.sort(d[inner])
    cut = order[min(len(order) - 1, extra)]
    hole = (d <= cut).astype(np.uint8)
    hole = cv2.morphologyEx(hole, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    n, labels, stats, _ = cv2.connectedComponentsWithStats(hole)
    keep = np.zeros_like(hole)
    for i in range(1, n):
        if stats[i, cv2.CC_STAT_AREA] >= max(40, 0.15 * extra):
            keep[labels == i] = 1
    return filled & ~(keep > 0)


def segment(robo, prompt, camera='cam_head', min_score=0.2):
    s = robo.segment(prompt, camera, min_score, include_contours=True)
    if not s.found:
        return None
    filled = mask_of(s)
    mask = carve_holes(filled, s.area_px, robo.image(camera))
    return dict(prompt=prompt, camera=camera, score=s.score, box=s.box, centroid=s.centroid,
                area=s.area_px, mask=mask, filled=int(filled.sum()), seg=s)


def overlay(robo, camera='cam_head', masks=(), points=(), lines=(), scale=2):
    """RGB overlay for review: mask outlines, world points/lines projected."""
    K, E = cam(robo, camera)
    im = Image.fromarray(np.asarray(robo.image(camera))).convert('RGB')
    dr = ImageDraw.Draw(im)
    cols = [(255, 0, 0), (0, 255, 0), (0, 160, 255), (255, 255, 0), (255, 0, 255), (0, 255, 255)]
    for i, m in enumerate(masks):
        if m is None:
            continue
        for outline in m['seg'].contours_rc or ():
            pts = [(int(c), int(r)) for r, c in outline]
            if len(pts) >= 3:
                dr.line(pts + [pts[0]], fill=cols[i % len(cols)], width=1)
    for i, p in enumerate(points):
        r, c = project(K, E, p)[0]
        dr.ellipse([c - 3, r - 3, c + 3, r + 3], outline=cols[i % len(cols)], width=2)
    for i, (a, b) in enumerate(lines):
        (r0, c0), (r1, c1) = project(K, E, [a, b])
        dr.line([(c0, r0), (c1, r1)], fill=cols[i % len(cols)], width=2)
    return im.resize((im.width * scale, im.height * scale))


def _rx(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[1.0, 0.0, 0.0], [0.0, c, -s], [0.0, s, c]])


def _ry(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, 0.0, s], [0.0, 1.0, 0.0], [-s, 0.0, c]])


def _rz(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, -s, 0.0], [s, c, 0.0], [0.0, 0.0, 1.0]])


def orientation(pitch, yaw, roll):
    """Gripper rotation for (pitch, yaw, roll) in degrees: Rz(90 + yaw) Ry(pitch) Rx(roll)."""
    return _rz(math.radians(90.0 + yaw)) @ _ry(math.radians(pitch)) @ _rx(math.radians(roll))


def angles(rot):
    """(pitch, yaw, roll) in degrees of a gripper rotation (not within a degree of vertical)."""
    point = rot[:, 0]
    pitch = math.degrees(math.asin(max(-1.0, min(1.0, -point[2]))))
    yaw = math.degrees(math.atan2(point[1], point[0])) - 90.0
    rest = orientation(pitch, yaw, 0.0).T @ rot
    roll = math.degrees(math.atan2(rest[2, 1], rest[1, 1]))
    wrap = lambda d: (d + 180.0) % 360.0 - 180.0
    return pitch, wrap(yaw), wrap(roll)


def used(robo):
    return int(robo.action_count())


def go(robo, arm, xyz, pitch=None, yaw=None, roll=None, path='line', gripper=0, label=''):
    """One move with a compact reply appended to LOG."""
    before = used(robo)
    m = robo.move_to([float(v) for v in xyz], arm=arm, gripper=gripper, pitch=pitch, yaw=yaw, roll=roll, path=path)
    rec = dict(label=label, arm=arm, reached=bool(m.reached), blocked=bool(getattr(m, 'blocked', False)),
               dist=float(getattr(m, 'dist_to_target_m', float('nan'))), note=getattr(m, 'note', None),
               ik_error=getattr(m, 'ik_error', None), actions=used(robo) - before, at=used(robo))
    LOG.append(rec)
    return rec


def approach(robo, arm, xyz, opening=None, label='', **kw):
    """Move an EMPTY hand to a pose with its fingers closed, then open it.

    With an open empty gripper the arm may take the pose turned half a turn
    about its pointing direction, which swaps the fingers and puts the wrist
    camera on the other side. A closed hand is taken exactly as asked.
    ``opening`` None leaves the hand closed; 1.0 opens fully.
    """
    rec = go(robo, arm, xyz, gripper=robo.CLOSE, label=label, **kw)
    if opening is not None and rec['reached']:
        before = used(robo)
        if opening >= 0.999:
            robo.set_gripper(arm, robo.OPEN)
        else:
            robo.set_gripper(arm, robo.OPEN, opening=opening)
        rec = dict(rec, actions=rec['actions'] + used(robo) - before, opened=opening)
    return rec


def glide(robo, arm, xyz, step_m=0.015, label='', **kw):
    """Straight move in short steps, one action each: no swing, low acceleration."""
    start = np.asarray(robo.state().arm(arm).tcp_pos, float)
    goal = np.asarray(xyz, float)
    n = max(1, int(math.ceil(np.linalg.norm(goal - start) / step_m)))
    before = used(robo)
    rec = None
    for k in range(1, n + 1):
        rec = go(robo, arm, start + (goal - start) * k / n, path='line', label=label, **kw)
        if not rec['reached'] and rec.get('ik_error'):
            break
    rec = dict(rec, actions=used(robo) - before, steps=n)
    return rec


def sheet(images, cols=4, size=(320, 240)):
    """Contact sheet of PIL/array images."""
    ims = [Image.fromarray(np.asarray(i)).convert('RGB').resize(size) for i in images]
    rows = (len(ims) + cols - 1) // cols
    out = Image.new('RGB', (cols * size[0], rows * size[1]))
    for i, im in enumerate(ims):
        out.paste(im, ((i % cols) * size[0], (i // cols) * size[1]))
    return out


SHAPES = {}


def foreground(rgb):
    """(tool-like, tray-like) boolean images: pixels that are not the brown table; teal pixels are the tray."""
    import cv2
    hsv = cv2.cvtColor(np.ascontiguousarray(np.asarray(rgb)[:, :, :3]), cv2.COLOR_RGB2HSV).astype(int)
    h, s, v = hsv[..., 0], hsv[..., 1], hsv[..., 2]
    teal = (h > 75) & (h < 105) & (s > 60)
    table = (h >= 3) & (h <= 14) & (s >= 60) & (v >= 50)
    yellow = (h >= 18) & (h <= 38) & (s > 110) & (v > 110)
    tool = (~table & ~teal) | yellow
    return tool, teal


def render(points, K, E, shape=(480, 640)):
    """Silhouette of world points in the image (points are about 2 mm apart)."""
    import cv2
    pc = (points - E[:3, 3]) @ E[:3, :3]
    col = np.round(K[0, 2] + K[0, 0] * pc[:, 0] / -pc[:, 2]).astype(int)
    row = np.round(K[1, 2] - K[1, 1] * pc[:, 1] / -pc[:, 2]).astype(int)
    ok = (row >= 0) & (row < shape[0]) & (col >= 0) & (col < shape[1])
    m = np.zeros(shape, np.uint8)
    m[row[ok], col[ok]] = 1
    return cv2.morphologyEx(m, cv2.MORPH_CLOSE, np.ones((3, 3), np.uint8)) > 0


def fit_shape(points, z, target, K, E, centre, span, steps=(0.012, 0.004, 0.0015, 0.0005), avoid=None):
    """Best (x, y) of a point set at height z: maximises the overlap ratio of its silhouette with a target image."""
    best = (-1.0, float(centre[0]), float(centre[1]))
    half = span
    for step in steps:
        n = max(1, int(round(half / step)))
        cx, cy = best[1], best[2]
        for i in range(-n, n + 1):
            for j in range(-n, n + 1):
                x, y = cx + i * step, cy + j * step
                m = render(points + np.array([x, y, z]), K, E, target.shape)
                a = int(m.sum())
                if a == 0:
                    continue
                r0, r1 = np.nonzero(m.any(axis=1))[0][[0, -1]]
                c0, c1 = np.nonzero(m.any(axis=0))[0][[0, -1]]
                win = (slice(max(0, r0 - 6), r1 + 7), slice(max(0, c0 - 6), c1 + 7))
                t = target[win]
                inter = int((m[win] & t).sum())
                union = a + int(t.sum()) - inter
                score = inter / max(1, union)
                if score > best[0]:
                    best = (score, x, y)
        half = step * 1.5
    return dict(xy=np.array(best[1:]), iou=best[0])


def table_xy(K, E, rc, z=TABLE_Z):
    r, c = float(rc[0]), float(rc[1])
    d = E[:3, :3] @ np.array([(c - K[0, 2]) / K[0, 0], -(r - K[1, 2]) / K[1, 1], -1.0])
    o = E[:3, 3]
    return (o + (z - o[2]) / d[2] * d)[:2]


def backproject(K, E, rows, cols, z):
    """World (x, y) where the rays through pixels (rows, cols) meet the horizontal plane at height z."""
    rows = np.asarray(rows, float)
    cols = np.asarray(cols, float)
    d = (E[:3, :3] @ np.stack([(cols - K[0, 2]) / K[0, 0], -(rows - K[1, 2]) / K[1, 1], -np.ones_like(rows)])).T
    o = E[:3, 3]
    t = (z - o[2]) / d[:, 2]
    return o[None, :2] + t[:, None] * d[:, :2]


def turn(theta):
    """2 x 2 rotation by theta radians (counter-clockwise seen from above)."""
    c, s = math.cos(theta), math.sin(theta)
    return np.array([[c, -s], [s, c]])


def outline(mask, K, E, z):
    """Frame and point set of one object outline in the head picture, on the plane at height z.

    ``theta`` is the turn of the outline's long axis from +y (radians, counter-clockwise seen from above); an outline
    less than 1.6 times as long as wide has no clear direction and gets 0. ``xy`` is the middle of the outline: halfway
    between its two ends along the long axis and at its area centroid across it. ``length`` and ``width`` are its extents
    along and across that axis (m), ``elong`` the ratio of its spreads, ``area`` its area (m^2), and ``points`` the outline
    as offsets from ``xy`` at height 0 (four per pixel), for ``render`` and ``fit_shape``.
    """
    r, c = np.nonzero(mask)
    r = r.astype(float)
    c = c.astype(float)
    P = backproject(K, E, r, c, z)
    du = backproject(K, E, r, c + 1.0, z) - P
    dv = backproject(K, E, r + 1.0, c, z) - P
    w = np.abs(du[:, 0] * dv[:, 1] - du[:, 1] * dv[:, 0])
    m = (P * w[:, None]).sum(0) / w.sum()
    D = P - m
    ev, V = np.linalg.eigh((D * w[:, None]).T @ D / w.sum())
    ax = V[:, 1] * (1.0 if V[1, 1] >= 0 else -1.0)
    elong = math.sqrt(max(ev[1], 0.0) / max(ev[0], 1e-12))
    theta = math.atan2(-ax[0], ax[1]) if elong >= 1.6 else 0.0
    R = turn(theta)
    s = D @ R[:, 1]
    u = D @ R[:, 0]
    mid = m + 0.5 * (s.min() + s.max()) * R[:, 1] if elong >= 1.6 else m
    sub = np.array([[-0.25, -0.25], [-0.25, 0.25], [0.25, -0.25], [0.25, 0.25]])
    pts = np.stack([backproject(K, E, r + dr, c + dc, z) for dr, dc in sub], axis=1).reshape(-1, 2) - mid
    return dict(xy=mid, theta=theta, length=float(s.max() - s.min()), width=float(u.max() - u.min()), elong=elong,
                area=float(w.sum()), points=np.c_[pts, np.zeros(len(pts))])


def tray_hull(tool, teal):
    """Tray region in the head picture, the shaded front wall included, as a filled convex region (or None)."""
    import cv2
    n, lab, stats, cen = cv2.connectedComponentsWithStats(teal.astype(np.uint8))
    if n < 2:
        return None
    k = 1 + int(np.argmax(stats[1:, cv2.CC_STAT_AREA]))
    blob = lab == k
    below = cv2.dilate(blob.astype(np.uint8), np.ones((29, 1), np.uint8), anchor=(0, 28)) > 0
    body = blob | (tool & below)
    hull = np.zeros_like(blob, np.uint8)
    cs, _ = cv2.findContours(body.astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    cv2.drawContours(hull, [cv2.convexHull(np.concatenate(cs))], -1, 1, -1)
    return hull > 0


def _crossing(p, start, stop, level):
    for r in range(max(0, start), min(len(p) - 1, stop)):
        a, b = p[r], p[r + 1]
        if (a - level) * (b - level) <= 0 and a != b:
            return r + (level - a) / (b - a)
    return None


def tray_frame(rgb, teal, K, E):
    """Tray frame from the head picture.

    The lit top of the tray is the largest region of bright teal pixels (holes filled). Its left and right edges, on the
    rim plane ``RIM_Z``, give the tray's middle across; the foot of its front wall on the table, found to a fraction of a
    pixel where the dark wall meets the table, gives its turn and the front line. Returns ``origin`` (world x, y of the
    middle of the front wall's foot), ``theta`` (radians, turn of the front line from +x, counter-clockwise seen from
    above), ``xy`` (middle of the tray: halfway between the side edges, ``TRAY_DEPTH`` / 2 behind the front line),
    ``width`` and ``depth`` (m, between the side edges, and from the front line to the far edge of the lit top), ``points`` (the lit top as offsets from ``xy`` at height 0), ``top`` (its
    image region) and ``spread`` (m: spread of the front-line points about their line), or None.
    """
    import cv2
    rgb = np.ascontiguousarray(np.asarray(rgb)[:, :, :3])
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV).astype(int)
    v = hsv[..., 2]
    table = (hsv[..., 0] >= 3) & (hsv[..., 0] <= 14) & (hsv[..., 1] >= 60) & (v >= 50)
    lit = cv2.morphologyEx((teal & (v >= 100)).astype(np.uint8), cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8))
    n, lab, st, _ = cv2.connectedComponentsWithStats(lit)
    if n < 2:
        return None
    k = 1 + int(np.argmax(st[1:, cv2.CC_STAT_AREA]))
    cs, _ = cv2.findContours((lab == k).astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)
    top = np.zeros(lit.shape, np.uint8)
    cv2.drawContours(top, cs, -1, 1, -1)
    top = top > 0
    x0, y0, w, h = st[k, :4]
    red = rgb[:, :, 0].astype(float)
    foot = []
    for c in range(x0 + int(0.2 * w), x0 + int(0.8 * w)):
        rows = np.nonzero(top[:, c])[0]
        r = rows.max() + 1
        while r < rgb.shape[0] - 1 and v[r, c] >= 100:
            r += 1
        t = r
        while t < rgb.shape[0] - 5 and not table[t, c]:
            t += 1
        if t - r > 30 or t >= rgb.shape[0] - 5:
            continue
        level = 0.5 * (np.median(red[r + 1:r + 4, c]) + np.median(red[t + 1:t + 4, c]))
        q = _crossing(red[:, c], t - 3, t + 2, level)
        if q is not None:
            foot.append((q + 0.5, c))
    if len(foot) < 10:
        return None
    foot = np.array(foot)
    F = backproject(K, E, foot[:, 0], foot[:, 1], TABLE_Z)
    m = F.mean(axis=0)
    ev, V = np.linalg.eigh(np.cov((F - m).T))
    d = V[:, 1] if V[0, 1] >= 0 else -V[:, 1]
    theta = math.atan2(d[1], d[0])
    R = turn(theta)
    side = []
    for r in range(y0 + int(0.15 * h), y0 + int(0.7 * h)):
        cc = np.nonzero(top[r])[0]
        side.append((r, cc.min() - 0.5, cc.max() + 0.5))
    side = np.array(side)
    xl = np.median((backproject(K, E, side[:, 0], side[:, 1], RIM_Z) @ R)[:, 0])
    xr = np.median((backproject(K, E, side[:, 0], side[:, 2], RIM_Z) @ R)[:, 0])
    yf = np.median((F @ R)[:, 1])
    origin = R @ np.array([0.5 * (xl + xr), yf])
    o = outline(top, K, E, RIM_Z)
    far = float(np.max((o['points'][:, :2] + o['xy']) @ R[:, 1]))
    xy = R @ np.array([0.5 * (xl + xr), yf + 0.5 * TRAY_DEPTH])
    pts = o['points'].copy()
    pts[:, :2] += o['xy'] - xy
    return dict(origin=origin, theta=theta, xy=xy, points=pts, top=top, width=float(xr - xl), depth=float(far - yf),
                spread=float(math.sqrt(max(ev[0], 0.0))))


def measure_scene(rgb, K, E, names=('hammer', 'wrench', 'pliers', 'tape_measure')):
    """Tray and tool frames from one head picture (arms out of the view).

    The tray frame comes from ``tray_frame``. Every other region on the table outside the tray is an outline on the plane
    at the pinch height (``outline``); the tools in ``names`` are told apart by the length and width of their outlines
    (``SIZE``), choosing the assignment with the smallest total size mismatch; a tool whose best match is off by more than
    0.5 (sum of the absolute log ratios of length and width) is not found. Returns per found object its frame
    (``xy``, ``theta``), ``iou`` (overlap of the outline drawn back into the picture with the region it came from),
    ``points`` and, for a tool, the size mismatch ``cost`` of its assignment and ``side`` ('left' or 'right' of the tray).
    """
    import cv2
    import itertools
    tool, teal = foreground(rgb)
    out = {}
    hull = tray_hull(tool, teal)
    tr = tray_frame(rgb, teal, K, E)
    if hull is None or tr is None:
        return out
    m = render(tr['points'] + np.array([tr['xy'][0], tr['xy'][1], RIM_Z]), K, E, hull.shape)
    tr['iou'] = float((m & tr['top']).sum()) / max(1, int((m | tr['top']).sum()))
    out['toolbox'] = tr
    rest = tool & ~(cv2.dilate(hull.astype(np.uint8), np.ones((7, 7), np.uint8)) > 0)
    n, lab, stats, cen = cv2.connectedComponentsWithStats(rest.astype(np.uint8))
    parts = []
    for i in range(1, n):
        if stats[i, cv2.CC_STAT_AREA] < 300:
            continue
        at = table_xy(K, E, (cen[i][1], cen[i][0]), TABLE_Z)
        if abs(at[0]) > 0.5 or not -0.3 < at[1] < 0.25:
            continue
        mask = lab == i
        o = outline(mask, K, E, TABLE_Z)
        m = render(o['points'] + np.array([o['xy'][0], o['xy'][1], TABLE_Z]), K, E, mask.shape)
        o['iou'] = float((m & mask).sum()) / max(1, int((m | mask).sum()))
        o['side'] = 'left' if o['xy'][0] < tr['origin'][0] else 'right'
        parts.append(o)
    parts = sorted(parts, key=lambda o: -o['area'])[:6]
    names = [k for k in names if k in SIZE]
    n = min(len(names), len(parts))
    choice = None
    for chosen in itertools.combinations(names, n):
        for pick_ in itertools.permutations(range(len(parts)), n):
            cost = [abs(math.log(parts[j]['length'] / SIZE[k][0])) + abs(math.log(parts[j]['width'] / SIZE[k][1])) for k, j in zip(chosen, pick_)]
            if choice is None or sum(cost) < choice[0]:
                choice = (sum(cost), chosen, pick_, cost)
    if choice is not None:
        for k, j, e in zip(choice[1], choice[2], choice[3]):
            if e < 0.5:
                out[k] = dict(parts[j], cost=float(e))
    return out


ARM_BASE = {'left': (-0.30, -0.45), 'right': (0.30, -0.45)}
# RGB upper-rim plane (±4 mm) and front-foot to far-rim depth (±5 mm).
RIM_Z = 0.8035
TRAY_DEPTH = 0.2738
# RGB head-mask extents reprojected to TABLE_Z. docs/store_tools_in_toolbox/applied_values.json
SIZE = {'hammer': (0.2349, 0.0868), 'wrench': (0.1808, 0.0469), 'pliers': (0.1656, 0.0650), 'tape_measure': (0.0745, 0.0715)}

TOOLS = {
    'hammer': dict(feel=True),
    'wrench': dict(),
    'pliers': dict(squeeze_again=False),
    'tape_measure': dict(),
}

ORDER = ('tape_measure', 'hammer', 'pliers', 'wrench')
S = dict(scene={}, placed={}, held=None, events=[])
SNAPS = []


def snap(robo, label, cameras=('cam_head',)):
    for c in cameras:
        im = Image.fromarray(np.asarray(robo.image(c))).convert('RGB')
        ImageDraw.Draw(im).text((6, 6), '%s %s @%d' % (label, c.replace('cam_', ''), used(robo)), fill=(255, 255, 0))
        SNAPS.append(im)


def tcp(robo, arm):
    return np.asarray(robo.state().arm(arm).tcp_pos, float)


def clear_arms(robo, arms=('left', 'right')):
    return {arm: None for arm in arms}


def move(robo, arm, xyz, label='', paths=('line', 'auto'), **kw):
    """One move, trying path styles in turn until one is reached."""
    rec = None
    for path in paths:
        rec = go(robo, arm, xyz, path=path, label=label if path == paths[0] else label + '/' + path, **kw)
        if rec['reached']:
            break
    return rec


def trim(robo, arm, xyz, tol=0.0007, tries=2, **kw):
    """Small corrective moves until the fingertip point is within tol of xyz in the horizontal plane."""
    e = tcp(robo, arm) - np.asarray(xyz, float)
    for _ in range(tries):
        if np.linalg.norm(e[:2]) < tol:
            break
        go(robo, arm, [xyz[0] - 0.9 * e[0], xyz[1] - 0.9 * e[1], xyz[2]], path='line', label='trim', **kw)
        e = tcp(robo, arm) - np.asarray(xyz, float)
    return e


def look(robo):
    """Head-view measurement of the tray and of the tools lying on the table (arms out of the view)."""
    K, E = cam(robo)
    rgb = np.asarray(robo.image('cam_head'))
    scene = measure_scene(rgb, K, E, names=[k for k in TOOLS if k not in S['placed']])
    for k in S['placed']:
        if k in S['scene']:
            scene[k] = S['scene'][k]
    for k, f in scene.items():
        if k == 'toolbox' or k not in S['placed']:
            SHAPES[k] = f['points']
    S.update(scene=scene, K=K, E=E)
    return scene


def outline_picture(robo, items, scale=2):
    """Head picture with the outline of each named shape drawn at a given (x, y, z)."""
    import cv2
    K, E = cam(robo)
    rgb = np.ascontiguousarray(np.asarray(robo.image('cam_head'))[:, :, :3])
    big = cv2.resize(rgb, None, fx=scale, fy=scale, interpolation=cv2.INTER_LANCZOS4)
    cols = {'toolbox': (255, 0, 255), 'hammer': (255, 0, 0), 'wrench': (0, 255, 0), 'pliers': (0, 160, 255), 'tape_measure': (255, 255, 0)}
    for name, xyz in items:
        if name not in SHAPES:
            continue
        m = render(SHAPES[name][::2] + np.asarray(xyz, float), K, E, rgb.shape[:2]).astype(np.uint8)
        m = cv2.resize(m, None, fx=scale, fy=scale, interpolation=cv2.INTER_NEAREST)
        cs, _ = cv2.findContours(m, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)
        cv2.drawContours(big, cs, -1, cols[name], 1)
    return Image.fromarray(big)


def slot_xyz(tool):
    """Measured tray origin on the rim plane. The caller looks and shifts if this seat is occupied."""
    t = S['scene']['toolbox']
    return np.array([float(t['origin'][0]), float(t['origin'][1]), RIM_Z])


def arm_of(tool):
    """The arm on the side of the tray where the tool was found."""
    return S['scene'][tool]['side']


def grasp_offset(tool):
    """Fingers close on the middle of the measured outline."""
    return np.zeros(2)


def survey(robo, clear=True):
    rec = clear_arms(robo) if clear else {}
    scene = look(robo)
    need = ('toolbox', 'hammer', 'wrench', 'pliers', 'tape_measure')
    ok = all(k in scene for k in need) and scene['toolbox']['iou'] > 0.9 and all(scene[k]['iou'] > 0.55 for k in need[1:] if k not in S['placed'])
    items = [(k, [scene[k]['xy'][0], scene[k]['xy'][1], RIM_Z if k == 'toolbox' else TABLE_Z]) for k in need if k in scene and k not in S['placed']]
    if 'toolbox' in scene:
        items += [(k, slot_xyz(k)) for k in need[1:]]
    return dict(ok=ok, image=outline_picture(robo, items), measured={k: dict(xy=np.round(f['xy'], 4).tolist(), overlap=round(f['iou'], 3)) for k, f in scene.items()})


def pitch_for(tool, robo=None):
    """The arm's current pitch. The distance is from the measured tray origin to that arm's base."""
    arm = arm_of(tool)
    tgt = slot_xyz(tool)[:2]
    d = float(np.linalg.norm(tgt - np.asarray(ARM_BASE[arm])))
    pitch = float(robo.state().arm(arm).pitch) if robo is not None else 0.0
    return pitch, d


def section_centre(robo, arm, xy, z_mid, half):
    """Wrist view from the pose above a lying tool: where, across the tool, the middle of its section under the hand is.

    World points on the line across the tool through ``xy`` at height ``z_mid`` are projected into the wrist picture; the run of
    non-table pixels nearest the hand's middle is the tool. Returns the offset of its middle from ``xy`` along x (metres) and
    its width, or None when no clear run is seen between the open fingers.
    """
    name = 'cam_%s_wrist' % arm
    K, E = cam(robo, name)
    rgb = np.asarray(robo.image(name))
    tool, _ = foreground(rgb)
    us = np.arange(-half, half + 1e-9, 0.00025)
    pts = np.c_[xy[0] + us, np.full(len(us), xy[1]), np.full(len(us), z_mid)]
    rc = np.round(project(K, E, pts)).astype(int)
    ok = (rc[:, 0] >= 0) & (rc[:, 0] < rgb.shape[0]) & (rc[:, 1] >= 0) & (rc[:, 1] < rgb.shape[1])
    on = np.zeros(len(us), bool)
    on[ok] = tool[rc[ok, 0], rc[ok, 1]]
    runs, start = [], None
    for i, v in enumerate(on):
        if v and start is None:
            start = i
        if (not v or i == len(on) - 1) and start is not None:
            end = i if not v else i + 1
            runs.append((us[start], us[end - 1]))
            start = None
    runs = [r for r in runs if r[1] - r[0] > 0.004 and r[0] > -half + 0.0005 and r[1] < half - 0.0005]
    if not runs:
        return None
    a, b = min(runs, key=lambda r: abs((r[0] + r[1]) / 2))
    return dict(offset=float((a + b) / 2), width=float(b - a))


def pick(robo, tool, pitch=None):
    """Pinch a lying tool at its balance point from above, fingers across it, and lift it straight up."""
    P = TOOLS[tool]
    arm = arm_of(tool)
    place_pitch, _ = pitch_for(tool, robo)
    if pitch is None:
        pitch = place_pitch
    origin = np.asarray(S['scene'][tool]['xy'], float)
    g = grasp_offset(tool)
    xy = origin + g
    opening = 1.0
    above = max(float(tcp(robo, arm)[2]), RIM_Z)
    recs = [approach(robo, arm, [xy[0], xy[1], above], pitch=pitch, yaw=0, roll=0, path='auto', opening=opening, label='pick-above')]
    if not recs[-1]['reached']:
        return dict(ok=False, why='pose above the tool not reached', replies=recs)
    trim(robo, arm, [xy[0], xy[1], above])
    seen = section_centre(robo, arm, xy, TABLE_Z, 0.5 * (0.002 + 0.109 * opening) - 0.003)
    if seen is not None and abs(seen['offset']) < 0.012:
        xy = xy + np.array([seen['offset'], 0.0])
        trim(robo, arm, [xy[0], xy[1], above], tol=0.0004)
    grasp_z = P.get('grasp_z', TABLE_Z)
    recs.append(go(robo, arm, [xy[0], xy[1], grasp_z], path='line', label='pick-down'))
    trim(robo, arm, [xy[0], xy[1], grasp_z], tries=1)
    t0 = tcp(robo, arm)
    if t0[2] > grasp_z + 0.012:
        recs.append(go(robo, arm, [xy[0], xy[1], above], path='line', label='pick-blocked-up'))
        return dict(ok=False, why='the hand could not come down on the tool', replies=recs)
    c = robo.set_gripper(arm, robo.CLOSE)
    width = float(getattr(c, 'width_m', 0.0))
    snap(robo, 'pinched ' + tool, ('cam_%s_wrist' % arm,))
    if not bool(getattr(c, 'holding', False)):
        robo.set_gripper(arm, robo.OPEN, opening=opening)
        recs.append(go(robo, arm, [xy[0], xy[1], above], path='line', label='pick-miss-up'))
        return dict(ok=False, why='closed on nothing', width=width, replies=recs)
    recs.append(glide(robo, arm, [t0[0], t0[1], t0[2] + 0.03], step_m=0.006, gripper=robo.CLOSE, label='pick-lift'))
    if P.get('squeeze_again', True):
        robo.set_gripper(arm, robo.CLOSE)
    recs.append(glide(robo, arm, [t0[0], t0[1], above], step_m=0.012, gripper=robo.CLOSE, label='pick-lift'))
    w2 = 0.002 + 0.109 * float(robo.state().arm(arm).gripper)
    if w2 <= 0.002:
        robo.set_gripper(arm, robo.OPEN, opening=opening)
        return dict(ok=False, why='tool slipped out while lifting', width=w2, replies=recs)
    S['held'] = dict(tool=tool, arm=arm, pitch=place_pitch, pick_pitch=pitch, offset=np.array([-g[0], origin[1] - t0[1]]), z_close=float(t0[2]), opening=opening)
    return dict(ok=True, width=round(width, 4), pitch=pitch, place_pitch=place_pitch, centred=None if seen is None else [round(seen['offset'], 4), round(seen['width'], 4)], tcp_at_close=np.round(t0, 4).tolist(), replies=recs)


def lower_until_contact(robo, arm, xy, z_from, z_to, step=0.004, lag=0.003):
    """Lower the closed hand in short steps; stop when it no longer follows (something is under the tool or the fingers).

    ``lag`` is how far above its target the hand settles when nothing is in its way (measured just before, about 3 mm)."""
    z = z_from
    while z > z_to + 1e-6:
        z = max(z_to, z - step)
        go(robo, arm, [xy[0], xy[1], z], path='line', gripper=robo.CLOSE, label='lower')
        at = tcp(robo, arm)
        if at[2] > z + max(lag, 0.0) + 0.005:
            return dict(contact=True, z=float(at[2]), asked=z)
    return dict(contact=False, z=float(tcp(robo, arm)[2]), asked=z)


def place(robo, offset=(0.0, 0.0)):
    """Carry the held tool over its place in the tray, lower it until it or the fingers touch, let go, leave upward."""
    h = S['held']
    tool, arm, pitch = h['tool'], h['arm'], h['pitch']
    P = TOOLS[tool]
    seat = slot_xyz(tool)
    tgt = seat[:2] - h['offset'] + np.asarray(offset, float)
    z_seat = h['z_close']
    carry_z = float(tcp(robo, arm)[2])
    start = tcp(robo, arm)
    p0 = float(robo.state().arm(arm).pitch)
    goal = np.array([tgt[0], tgt[1], carry_z])
    n = max(1, int(math.ceil(np.linalg.norm(goal - start) / 0.010)))
    recs = []
    for k in range(1, n + 1):
        recs.append(go(robo, arm, start + (goal - start) * k / n, pitch=p0 + (pitch - p0) * k / n, yaw=0, roll=0, path='line', gripper=robo.CLOSE, label='place-over'))
        if not recs[-1]['reached'] and recs[-1].get('ik_error'):
            break
    for _ in range(3):
        left = goal - tcp(robo, arm)
        if np.linalg.norm(left[:2]) <= 0.004:
            break
        part = tcp(robo, arm) + left * min(1.0, 0.04 / max(np.linalg.norm(left), 1e-6))
        recs.append(go(robo, arm, part, pitch=pitch, yaw=0, roll=0, path='auto', gripper=robo.CLOSE, label='place-over/auto'))
        if not recs[-1]['reached']:
            break
    if np.linalg.norm(tcp(robo, arm)[:2] - tgt) > 0.01:
        down = put_down(robo)
        return dict(ok=False, why='pose over the tray not reached; the tool was laid down again', put_down=down, replies=recs)
    if 0.002 + 0.109 * float(robo.state().arm(arm).gripper) <= 0.002:
        snap(robo, 'LOST ' + tool, ('cam_%s_wrist' % arm,))
        S['held'] = None
        clear_arms(robo, arms=(arm,))
        return dict(ok=False, why='the tool slid out of the fingers during the carry and lies where it fell', replies=recs)
    trim(robo, arm, [tgt[0], tgt[1], carry_z], gripper=robo.CLOSE)
    recs.append(glide(robo, arm, [tgt[0], tgt[1], z_seat + 0.035], step_m=0.010, gripper=robo.CLOSE, label='place-down'))
    e = trim(robo, arm, [tgt[0], tgt[1], z_seat + 0.035], gripper=robo.CLOSE)
    lag = float(tcp(robo, arm)[2] - (z_seat + 0.035))
    snap(robo, 'over slot ' + tool, ('cam_%s_wrist' % arm,))
    low = lower_until_contact(robo, arm, tgt, z_seat + 0.035, z_seat + 0.002, lag=lag)
    tries = [dict(shift=[0.0, 0.0], above_seat=round(low['z'] - z_seat, 4))]
    shift = np.zeros(2)
    for _ in range(3 if P.get('feel') else 0):
        up = low['z'] - z_seat
        if not low['contact'] or up <= 0.020:
            break
        if 0.002 + 0.109 * float(robo.state().arm(arm).gripper) <= 0.002:
            break
        shift = shift + np.array([0.0, -0.002])
        t2 = tgt + shift
        glide(robo, arm, [tgt[0], tgt[1], low['z'] + 0.012], step_m=0.006, gripper=robo.CLOSE, label='reseat-up')
        go(robo, arm, [t2[0], t2[1], low['z'] + 0.012], path='line', gripper=robo.CLOSE, label='reseat-shift')
        trim(robo, arm, [t2[0], t2[1], low['z'] + 0.012], gripper=robo.CLOSE)
        low = lower_until_contact(robo, arm, t2, low['z'] + 0.012, z_seat + 0.002, lag=lag)
        tries.append(dict(shift=np.round(shift, 4).tolist(), above_seat=round(low['z'] - z_seat, 4)))
    at = tcp(robo, arm)
    robo.set_gripper(arm, robo.OPEN, opening=h['opening'])
    recs.append(go(robo, arm, [at[0], at[1], carry_z], path='line', label='place-up'))
    clear_arms(robo, arms=(arm,))
    S['held'] = None
    S['placed'][tool] = dict(target=np.round(tgt, 4).tolist(), released_at=np.round(at, 4).tolist(), above_seat=round(float(at[2] - z_seat), 4), contact=low['contact'])
    return dict(ok=True, tool=tool, released_at=np.round(at, 4).tolist(), above_seat=round(float(at[2] - z_seat), 4), contact=low['contact'],
                xy_error=np.round(e[:2], 4).tolist(), tries=tries, replies=recs)


def put_down(robo, clear=True):
    """Lay the held tool down where the hand is (on the table, or back toward the table if the hand is over the tray)."""
    h = S['held']
    if h is None:
        return dict(ok=True, why='nothing held')
    arm = h['arm']
    at = tcp(robo, arm)
    tb = S['scene']['toolbox']
    t = tb['xy']
    if abs(at[0] - t[0]) < 0.5 * tb['width'] + 0.052 and abs(at[1] - t[1]) < 0.5 * TRAY_DEPTH + 0.052:
        side = -1.0 if arm == 'left' else 1.0
        glide(robo, arm, [t[0] + side * (0.5 * tb['width'] + 0.101), at[1], at[2]], step_m=0.010, gripper=robo.CLOSE, label='put-down-clear')
        at = tcp(robo, arm)
    glide(robo, arm, [at[0], at[1], h['z_close'] + 0.004], step_m=0.008, gripper=robo.CLOSE, label='put-down')
    at = tcp(robo, arm)
    robo.set_gripper(arm, robo.OPEN, opening=h['opening'])
    go(robo, arm, [at[0], at[1], max(float(at[2]), RIM_Z)], path='line', label='put-down-up')
    if clear:
        clear_arms(robo, arms=(arm,))
    S['scene'][h['tool']]['xy'] = at[:2] + h['offset']
    S['held'] = None
    return dict(ok=True, tool=h['tool'], at=np.round(at[:2] + h['offset'], 4).tolist())


def relay_spot(tool):
    """No stored mid-carry point. The tool is carried to the measured tray in one motion."""
    return None


def relay(robo, tool, spot):
    """First half of a long carry: take the tool from straight above, carry it level to ``spot`` on the table and lay it down.

    The wrench turns slowly in the pinch while it is carried sideways (about 0.15 degrees per centimetre); after 35 to 40 cm
    its balance is lost and it slides out. Two short carries
    with a new pinch in between stay below that."""
    p = pick(robo, tool)
    if not p['ok']:
        return p
    h = S['held']
    arm = h['arm']
    start = tcp(robo, arm)
    goal = np.array([spot[0] - h['offset'][0], spot[1] - h['offset'][1], start[2]])
    glide(robo, arm, goal, step_m=0.010, gripper=robo.CLOSE, label='relay')
    if 0.002 + 0.109 * float(robo.state().arm(arm).gripper) <= 0.002:
        S['held'] = None
        return dict(ok=False, why='the tool slid out of the fingers during the carry and lies where it fell')
    down = put_down(robo, clear=False)
    return dict(ok=True, relay=down)


def store(robo, tool):
    if tool not in S['scene']:
        return dict(ok=False, tool=tool, stage='survey', why='not found on the table by the last survey')
    spot = relay_spot(tool)
    if spot is not None:
        r = relay(robo, tool, spot)
        if not r['ok']:
            return dict(ok=False, tool=tool, stage='relay', why=r.get('why'), pick=brief(r))
    p = pick(robo, tool)
    if not p['ok']:
        return dict(ok=False, tool=tool, stage='pick', why=p.get('why'), pick=brief(p), moves=[(r['label'], r['reached'], round(r['dist'], 4)) for r in p.get('replies', [])])
    q = place(robo)
    return dict(ok=q['ok'], tool=tool, stage='place', why=q.get('why'), pick=brief(p), place=brief(q))


def finish(robo):
    home = None
    for _ in range(3):
        home = robo.home()
        if bool(getattr(home, 'reached', False)):
            break
    return dict(ok=bool(getattr(home, 'reached', False)), home=str(home)[:200])


def brief(d, drop=('mask', 'replies', 'image')):
    out = {}
    for k, v in d.items():
        if k in drop:
            continue
        if isinstance(v, np.ndarray):
            v = np.round(v, 4).tolist()
        elif isinstance(v, dict):
            v = brief(v, drop)
        out[k] = v
    return out


def check(robo, clear=True):
    """Head view of the tray (arms out of the view): where each tool lies in the tray, by its outline seen on the table.

    Returns per tool the offset of the best-fitting position from its resting place and how much of its outline is
    covered by non-tray pixels inside the tray; a low overlap or a large offset means the tool is missing, turned or
    not lying flat in its place. ``None`` for a tool whose outline was not measured on the table in this session.
    """
    import cv2
    if clear:
        clear_arms(robo)
    K, E = cam(robo)
    rgb = np.asarray(robo.image('cam_head'))
    tool, teal = foreground(rgb)
    sh = SHAPES
    inside = tray_hull(tool, teal)
    if inside is None:
        return dict(tools={}, image=outline_picture(robo, []))
    inside = cv2.erode(inside.astype(np.uint8), np.ones((9, 9), np.uint8)) > 0
    target = tool & inside
    out = {}
    for name in ('hammer', 'wrench', 'pliers', 'tape_measure'):
        seat = slot_xyz(name)
        if name not in sh:
            out[name] = dict(offset=None, overlap=None)
            continue
        f = fit_shape(sh[name], seat[2], target, K, E, seat[:2], 0.012, steps=(0.004, 0.002, 0.001))
        out[name] = dict(offset=np.round(f['xy'] - seat[:2], 4).tolist(), overlap=round(f['iou'], 3))
    im = outline_picture(robo, [(k, slot_xyz(k)) for k in out])
    return dict(tools=out, image=im)


NAMES = {'hammer': 'hammer', 'wrench': 'wrench', 'pliers': 'pliers', 'tape_measure': 'tape measure'}


class Routines:
    """Stage calls for one episode. Each returns a dict: ok, reason, measured, action_count, image (a labelled picture or contact sheet)."""

    def __init__(self, robo):
        self.robo = robo

    def _out(self, ok, reason, measured, image=None):
        if image is None and SNAPS:
            image = sheet(SNAPS, cols=3, size=(480, 360))
        del SNAPS[:]
        return dict(ok=bool(ok), reason=reason, measured=measured, action_count=self.robo.action_count(), image=image)

    def show(self, out, display):
        """Print the result without the picture, then show the picture."""
        print(json.dumps({k: v for k, v in out.items() if k != 'image'}, default=str))
        if out.get('image') is not None:
            display(out['image'])

    def survey(self):
        """Both arms out of the view; find the tray and the four tools on the table."""
        r = survey(self.robo)
        del SNAPS[:]
        return self._out(r['ok'], None if r['ok'] else 'tray or a tool not found clearly', r['measured'], r['image'])

    def store(self, name):
        """Pick one tool ('tape_measure', 'pliers', 'wrench', 'hammer') from the table and put it into its place in the tray."""
        name = str(name)
        if name not in TOOLS:
            return self._out(False, 'unknown tool name; use one of %s' % (ORDER,), {})
        if not S['scene']:
            return self._out(False, 'call survey() first', {})
        if name in S['placed']:
            return self._out(False, 'this tool was already put into the tray; look at it with check()', dict(placed=S['placed'][name]))
        s = store(self.robo, name)
        if not s['ok'] and 'laid down again' in str(s.get('why')):
            s = store(self.robo, name)
        snap(self.robo, 'after ' + name)
        return self._out(s['ok'], s.get('why'), {k: v for k, v in s.items() if k not in ('ok', 'why')})

    def store_all(self):
        """Store every tool that is not in the tray yet, in the tested order. Stops after the first tool that fails."""
        if not S['scene']:
            return self._out(False, 'call survey() first', {})
        rows = {}
        for name in ORDER:
            if name in S['placed']:
                continue
            s = store(self.robo, name)
            if not s['ok'] and 'laid down again' in str(s.get('why')):
                s = store(self.robo, name)
            rows[name] = dict(ok=s['ok'], why=s.get('why'), place={k: v for k, v in (s.get('place') or {}).items() if k in ('released_at', 'above_seat', 'contact', 'tries')})
            snap(self.robo, 'after ' + name)
            if not s['ok']:
                return self._out(False, '%s: %s' % (name, s.get('why')), rows)
        return self._out(True, None, rows)

    def check(self):
        """Arms out of the view; head picture of the tray with the outline of each tool at its resting place."""
        c = check(self.robo)
        del SNAPS[:]
        return self._out(True, None, c['tools'], c['image'])

    def finish(self):
        """Both arms return to the start pose."""
        r = finish(self.robo)
        return self._out(r['ok'], None if r['ok'] else 'arms not at the start pose yet: call finish again', dict(home=r['home']))


_ROUTINES = {}


def routines(robo):
    """The one Routines object of this episode."""
    if 'r' not in _ROUTINES or _ROUTINES['r'].robo is not robo:
        _ROUTINES['r'] = Routines(robo)
    return _ROUTINES['r']
